Definition LRW (n : Z) : Z := Z.max n 0 + 2 ^ 23.

Definition evr (n : Z) (st : mstate) (e : ev) : Prop :=
  match e with
  | EMmap a len prot flags =>
      Z.land flags MAP_FIXED = 0 ->
      (prot = PROT_NONE -> len <= Z.max (2 ^ (cshift st + 1)) 2 * PGSZ) /\ (prot <> PROT_NONE -> len <= LRW n)
  | _ => True
  end.

