Definition is_undef (e : ev) : bool := match e with EUndef _ => true | _ => false end.

Fixpoint lall {R} (P : R -> Prop) (t : M R) {struct t} : Prop :=
  match t with
  | SRet r => P r
  | SVis e k => if is_undef e then True else forall z, lall P (k z)
  end.

Fixpoint nok {R} (C : ev -> R -> Prop) (t : M R) {struct t} : Prop :=
  match t with
  | SRet _ => True
  | SVis e k => if is_undef e then True else (forall z, lall (C e) (k z)) /\ (forall z, nok C (k z))
  end.

