Fixpoint node_at {R} (t : M R) (ans : list Z) (e : ev) (k : Z -> M R) {struct t} : Prop :=
  match t with
  | SRet _ => False
  | SVis e' k' =>
      match ans with
      | [] => e' = e /\ k' = k
      | a :: ans' => if is_undef e' then False else node_at (k' a) ans' e k
      end
  end.

Section TOK.
Context {R : Type} (n : Z) (P : R -> Prop) (C : ev -> R -> Prop).

Definition TOK (st : mstate) (t : M R) : Prop :=
  lall P t /\ nok C t /\ (forall e, evr n st e -> lall (C e) t).

Definition KOK {X} (st : mstate) (k : mstate -> X -> M R) : Prop :=
  forall st' x, REL st st' -> TOK st' (k st' x).
Definition KOK0 (st : mstate) (k : mstate -> M R) : Prop :=
  forall st', REL st st' -> TOK st' (k st').

