Definition am_init (st : mstate) : mstate :=
  if c_init_done (ctx st) =? 0 then upd_ctx (fun c => set_init_done 1 (set_secret (s_secret st) c)) st else st.

Definition KOKI (st : mstate) (k : mstate -> optr -> M R) : Prop :=
  forall st' x, REL st st' -> cinit st' = 1 -> TOK st' (k st' x).

Lemma alloc_meta_tok st (k : mstate -> optr -> M R) bail :
  (cinit st = 0 \/ cinit st = 1) -> KOKI st k -> TOK st (alloc_meta st k bail).
