Definition LRQ (n : Z) : Z := Z.max n 0 + 2 ^ 22 + 12.

Section WALK3.
Context {R : Type} (n : Z) (P : R -> Prop) (C : ev -> R -> Prop).
Notation TOK := (TOK n P C).
Notation KOK := (KOK n P C).
Notation KOK0 := (KOK0 n P C).
Notation KOKI := (KOKI n P C).
Variable lay : layout_hook.
Hypothesis LAYH : forall st p, s_ctx (lh_hdr lay st p) = s_ctx st.
Hypothesis LAYN : forall st g idx j size cnt, s_ctx (lh_nest lay st g idx j size cnt) = s_ctx st.

