Section WALKF.
Context {R : Type} (n : Z) (P : R -> Prop) (C : ev -> R -> Prop).
Notation TOK := (TOK n P C).
Notation KOK := (KOK n P C).
Notation KOK0 := (KOK0 n P C).

Lemma dec_slots_tok st p (k : aptr -> Z -> M R) bail : (forall m idx, TOK st (k m idx)) -> TOK st (dec_slots st p k bail).
Proof.
