Lemma alloc_meta_leaf_init {O} (pans : O -> aptr -> Z -> Z -> Z) pupd (o : O) st ans r :
  (cinit st = 0 \/ cinit st = 1) ->
  follow (prun pans pupd o (alloc_meta st (fun x (y : optr) => SRet (Some (x, y))) (SRet None))) ans = Some r ->
  match snd r with Some (st2, _) => cinit st2 = 1 /\ REL st st2 | None => True end.
